from sys import stdin
from math import gcd
n = int(stdin.readline())
iset = set()
for _ in range(n):
	(k, b) = map(int, stdin.readline().split())
	if k != 0:
		if b == 0:
			iset.add((0, 1))
		else:
			x = gcd(k, b)
			if k * b > 0:
				iset.add((abs(b // x), abs(k // x)))
			else:
				iset.add((-abs(b // x), abs(k // x)))
print(len(iset))
